148: // RegisterLayerFallbacks 把标准层下的 profile 注册进 registry，作为**兜底**来源。
149: //
150: // 优先级（高 → 低）：config 注册项 > profiles.root 下可用的同名目录 >
151: // project 层 > user 层。前两者仍然优先，既有语义不变；只有"config/root 都给不出
152: // 可用目录"的名字才由层目录补齐。
153: //
154: // 为什么需要它：TUI/API 的 create/duplicate/import/move 把 profile 落在层根
155: // （LayerRoot 是唯一写目标），而 registry 只认 config 注册项与 profiles.root。
156: // 不补这一层就会出现"创建成功 → /profile use 报未知 profile"的写读分叉。
157: //
158: // 返回被注册的层 profile（按注册顺序），供调用方做"来源=层"的展示与测试断言。
159: func RegisterLayerFallbacks(registry *Registry) []LayerProfile {
160: 	if registry == nil {
161: 		return nil
162: 	}
163: 	known := make(map[string]struct{})
164: 	for _, entry := range registry.Entries() {
165: 		known[entry.Name] = struct{}{}
166: 	}
167: 	defaultRoot := strings.TrimSpace(registry.DefaultRoot())
168: 	added := make([]LayerProfile, 0, 4)
169: 	for _, candidate := range LayerProfiles() {
170: 		if _, exists := known[candidate.Name]; exists {
171: 			continue
172: 		}
173: 		// profiles.root 下存在同名可用目录时以 root 为准（显式配置优先于层发现）。
174: 		if defaultRoot != "" && hasProfileFile(filepath.Join(defaultRoot, candidate.Name)) {
175: 			continue
176: 		}
177: 		if err := registry.Register(candidate.Name, candidate.Root); err != nil {
178: 			continue
179: 		}
180: 		known[candidate.Name] = struct{}{}
181: 		added = append(added, candidate)
182: 	}
183: 	return added
184: }
