14: // 内置 profile 模板（实施方案 Batch 2）：
15: //   - 模板随二进制分发（go:embed），不依赖仓库 checkout；
16: //   - examples/profiles/ 保留为参考样例，与模板同源由一致性测试保证；
17: //   - 渲染只做占位符替换与 agents/default 目录改名，不做任何"智能"改写。
18: //
19: //go:embed templates
20: var templateFS embed.FS
21: 
22: const (
23: 	templateRootDir = "templates"
24: 
25: 	// templateMetadataFile is the per-template metadata file. It drives
26: 	// ListTemplates/RenderTemplate and is never part of the rendered output.
27: 	templateMetadataFile = "template.yaml"
28: 
29: 	placeholderName        = "{{name}}"
30: 	placeholderDescription = "{{description}}"
31: 	placeholderAgent       = "{{agent}}"
32: 
33: 	// TemplateDefaultAgent is the agent id every built-in template ships with.
34: 	TemplateDefaultAgent = "default"
35: 
36: 	// templateAgentDir is the directory every template stores its agent under;
37: 	// RenderTemplate renames it when a different agent id is requested.
38: 	templateAgentDir = "agents/" + TemplateDefaultAgent
39: )
40: 
41: // TemplateInfo describes one built-in profile template.
42: type TemplateInfo struct {
43: 	Name         string `json:"name"`
44: 	Description  string `json:"description"`
45: 	DefaultAgent string `json:"default_agent"`
46: 	// Files are the rendered profile-relative paths for the default agent,
47: 	// in deterministic order (useful for `profile create --dry-run`).
48: 	Files []string `json:"files"`
49: }
50: 
51: type templateMetadata struct {
52: 	Name         string `yaml:"name"`
53: 	Description  string `yaml:"description"`
54: 	DefaultAgent string `yaml:"default_agent"`
55: }
56: 
57: // TemplateNames returns the built-in template names in deterministic order.
58: func TemplateNames() []string {
59: 	entries, err := fs.ReadDir(templateFS, templateRootDir)
60: 	if err != nil {
61: 		return nil
62: 	}
63: 	names := make([]string, 0, len(entries))
64: 	for _, entry := range entries {
65: 		if !entry.IsDir() {
66: 			continue
67: 		}
68: 		names = append(names, entry.Name())
69: 	}
70: 	sort.Strings(names)
71: 	return names
72: }
73: 
74: // ListTemplates returns metadata for every built-in template, sorted by name.
75: func ListTemplates() []TemplateInfo {
76: 	names := TemplateNames()
77: 	infos := make([]TemplateInfo, 0, len(names))
78: 	for _, name := range names {
79: 		meta, err := loadTemplateMetadata(name)
80: 		if err != nil {
81: 			continue
82: 		}
83: 		files, err := renderTemplateFiles(name, name, meta.Description, TemplateDefaultAgent)
84: 		if err != nil {
85: 			continue
86: 		}
87: 		paths := make([]string, 0, len(files))
88: 		for rel := range files {
89: 			paths = append(paths, rel)
90: 		}
91: 		sort.Strings(paths)
92: 		infos = append(infos, TemplateInfo{
93: 			Name:         name,
94: 			Description:  meta.Description,
95: 			DefaultAgent: TemplateDefaultAgent,
96: 			Files:        paths,
97: 		})
98: 	}
99: 	return infos
100: }
101: 
102: // RenderTemplate renders the built-in template <name> for a profile called
103: // profileName whose default agent is agentID (empty = TemplateDefaultAgent).
104: //
105: // 渲染规则：内容中的 {{name}} / {{description}} / {{agent}} 占位符被替换；
106: // agentID 非默认时，agents/default/ 前缀改名为 agents/<agentID>/。
107: // 返回值以 profile 相对路径（slash 分隔）为键。
108: func RenderTemplate(name, profileName, agentID string) (map[string][]byte, error) {
109: 	name = strings.TrimSpace(name)
110: 	if name == "" {
111: 		return nil, fmt.Errorf("profile template name is required")
112: 	}
113: 	profileName = strings.TrimSpace(profileName)
114: 	if profileName == "" {
115: 		return nil, fmt.Errorf("profile name is required")
116: 	}
117: 	agentID = strings.TrimSpace(agentID)
118: 	if agentID == "" {
119: 		agentID = TemplateDefaultAgent
120: 	}
121: 	if err := validateTemplateAgentID(agentID); err != nil {
122: 		return nil, err
123: 	}
124: 
125: 	meta, err := loadTemplateMetadata(name)
126: 	if err != nil {
127: 		return nil, err
128: 	}
129: 	return renderTemplateFiles(name, profileName, meta.Description, agentID)
130: }
131: 
132: func renderTemplateFiles(templateName, profileName, description, agentID string) (map[string][]byte, error) {
133: 	dir := path.Join(templateRootDir, templateName)
134: 	files := make(map[string][]byte)
135: 	err := fs.WalkDir(templateFS, dir, func(filePath string, entry fs.DirEntry, walkErr error) error {
136: 		if walkErr != nil {
137: 			return walkErr
138: 		}
139: 		if entry.IsDir() {
140: 			return nil
141: 		}
142: 		rel := strings.TrimPrefix(path.Clean(filePath), path.Clean(dir)+"/")
143: 		if rel == templateMetadataFile {
144: 			return nil
145: 		}
146: 		content, err := fs.ReadFile(templateFS, filePath)
147: 		if err != nil {
148: 			return err
149: 		}
150: 		rendered := renderTemplateContent(string(content), profileName, description, agentID)
151: 		files[rewriteTemplateAgentDir(rel, agentID)] = []byte(rendered)
152: 		return nil
153: 	})
154: 	if err != nil {
155: 		return nil, err
156: 	}
157: 	if len(files) == 0 {
158: 		return nil, fmt.Errorf("profile template %q has no files", templateName)
159: 	}
160: 	return files, nil
161: }
162: 
163: func renderTemplateContent(content, profileName, description, agentID string) string {
164: 	content = strings.ReplaceAll(content, placeholderName, profileName)
165: 	content = strings.ReplaceAll(content, placeholderDescription, description)
166: 	content = strings.ReplaceAll(content, placeholderAgent, agentID)
167: 	return content
168: }
169: 
170: func rewriteTemplateAgentDir(rel, agentID string) string {
171: 	if agentID == TemplateDefaultAgent {
172: 		return rel
173: 	}
174: 	prefix := templateAgentDir + "/"
175: 	if strings.HasPrefix(rel, prefix) {
176: 		return "agents/" + agentID + "/" + strings.TrimPrefix(rel, prefix)
177: 	}
178: 	return rel
179: }
180: 
181: func loadTemplateMetadata(name string) (templateMetadata, error) {
182: 	meta := templateMetadata{}
183: 	metaPath := path.Join(templateRootDir, name, templateMetadataFile)
184: 	raw, err := fs.ReadFile(templateFS, metaPath)
185: 	if err != nil {
186: 		return meta, fmt.Errorf("unknown profile template %q (available: %s)",
187: 			name, strings.Join(TemplateNames(), ", "))
188: 	}
189: 	if err := yaml.Unmarshal(raw, &meta); err != nil {
190: 		return meta, fmt.Errorf("parse template metadata %s: %w", metaPath, err)
191: 	}
192: 	if strings.TrimSpace(meta.Description) == "" {
193: 		meta.Description = strings.TrimSpace(meta.Name)
194: 	}
195: 	return meta, nil
196: }
197: 
198: // validateTemplateAgentID keeps generated agent directory names portable and
199: // path-safe (they become directory names under agents/).
200: func validateTemplateAgentID(agentID string) error {
201: 	for _, r := range agentID {
202: 		switch {
203: 		case r >= 'a' && r <= 'z':
204: 		case r >= 'A' && r <= 'Z':
205: 		case r >= '0' && r <= '9':
206: 		case r == '-' || r == '_' || r == '.':
207: 		default:
208: 			return fmt.Errorf("agent id %q contains unsupported character %q (allowed: letters, digits, '-', '_', '.')", agentID, r)
209: 		}
210: 	}
211: 	return nil
212: }

