1255: func TestHandleChatWebAPISessions_OrderingCurrentNotPinned(t *testing.T) {
1256: 	// 排序语义：
1257: 	//   - 默认（无 sort 参数）与 ?sort=created_at：按创建时间降序
1258: 	//   - ?sort=updated_at：按更新时间降序
1259: 	// 两种模式下当前会话都不置顶（带 current 标记但不排第一）。
1260: 	// 构造 CreatedAt 与 UpdatedAt 顺序不同的会话（oldest 最后再 Save 一次），
1261: 	// 使两种排序产生不同结果，验证排序参数真实生效。
1262: 	storage := runtimechat.NewInMemoryStorage()
1263: 	manager := runtimechat.NewSessionManager(storage, nil)
1264: 	t.Cleanup(manager.Stop)
1265: 
1266: 	ctx := context.Background()
1267: 	mk := func(title string) *runtimechat.Session {
1268: 		t.Helper()
1269: 		s, err := manager.Create(ctx, "test-user")
1270: 		if err != nil {
1271: 			t.Fatalf("manager.Create: %v", err)
1272: 		}
1273: 		s.Metadata.Title = title
1274: 		s.AddMessage(*runtimetypes.NewUserMessage("conversation seed"))
1275: 		if err := storage.Save(ctx, s); err != nil {
1276: 			t.Fatalf("storage.Save: %v", err)
1277: 		}
1278: 		time.Sleep(2 * time.Millisecond) // 保证下一个 Create/Save 的时间戳严格更新
1279: 		return s
1280: 	}
1281: 
1282: 	oldestCreated := mk("oldest-created") // CreatedAt 最旧
1283: 	current := mk("current-mid")          // 创建于中间，设为当前会话
1284: 	newestCreated := mk("newest-created") // CreatedAt 最新
1285: 	time.Sleep(2 * time.Millisecond)
1286: 	// 再 Save 一次 oldestCreated：其 UpdatedAt 变成最新，与 CreatedAt 顺序相反。
1287: 	if err := storage.Save(ctx, oldestCreated); err != nil {
1288: 		t.Fatalf("storage.Save(oldestCreated): %v", err)
1289: 	}
1290: 
1291: 	session := newWebTestSession()
1292: 	session.SessionManager = manager
1293: 	session.SessionUserID = "test-user"
1294: 	session.RuntimeSession = current
1295: 	withWebTestSession(t, session)
1296: 
1297: 	fetchOrder := func(sortParam string) ([]string, string) {
1298: 		t.Helper()
1299: 		target := ChatWebAPISessionsPath
1300: 		if sortParam != "" {
1301: 			target += "?sort=" + sortParam
1302: 		}
1303: 		req := httptest.NewRequest(http.MethodGet, target, nil)
1304: 		rec := httptest.NewRecorder()
1305: 		HandleChatWebAPISessions(rec, req)
1306: 
1307: 		if rec.Code != http.StatusOK {
1308: 			t.Fatalf("status = %d, want 200", rec.Code)
1309: 		}
1310: 		var body struct {
1311: 			Sessions []chatWebSessionListItem `json:"sessions"`
1312: 			Current  string                   `json:"current_session_id"`
1313: 		}
1314: 		if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
1315: 			t.Fatalf("unmarshal: %v", err)
1316: 		}
1317: 		if len(body.Sessions) != 3 {
1318: 			t.Fatalf("sessions len = %d, want 3", len(body.Sessions))
1319: 		}
1320: 		if body.Current != current.ID {
1321: 			t.Fatalf("current_session_id = %q, want %q", body.Current, current.ID)
1322: 		}
1323: 		gotIDs := make([]string, 0, len(body.Sessions))
1324: 		var gotCurrent string
1325: 		for _, item := range body.Sessions {
1326: 			gotIDs = append(gotIDs, item.ID)
1327: 			if item.Current {
1328: 				gotCurrent = item.ID
1329: 			}
1330: 		}
1331: 		return gotIDs, gotCurrent
1332: 	}
1333: 
1334: 	assertOrder := func(sortParam string, wantOrder []string) {
1335: 		t.Helper()
1336: 		gotIDs, gotCurrent := fetchOrder(sortParam)
1337: 		for i, want := range wantOrder {
1338: 			if gotIDs[i] != want {
1339: 				t.Fatalf("sort=%q order[%d] = %q, want %q (full: %v)", sortParam, i, gotIDs[i], want, gotIDs)
1340: 			}
1341: 		}
1342: 		if gotCurrent != current.ID {
1343: 			t.Fatalf("sort=%q current flag on %q, want %q", sortParam, gotCurrent, current.ID)
1344: 		}
1345: 	}
1346: 
1347: 	// 创建时间降序：newest > current > oldest；当前会话（中间创建）不置顶。
1348: 	createdOrder := []string{newestCreated.ID, current.ID, oldestCreated.ID}
1349: 	assertOrder("", createdOrder)
1350: 	assertOrder("created_at", createdOrder)
1351: 	// 更新时间降序：oldestCreated（最后 Save）> newest > current。
1352: 	assertOrder("updated_at", []string{oldestCreated.ID, newestCreated.ID, current.ID})
1353: }
