106: // 目标校验等）必须走这里：Get 会把整段 prompt 投影反序列化进内存，而会话库
107: // 连接池恒为单连接（SetMaxOpenConns(1)），逐个候选 Get 会让列表请求把并发读
108: // （启动期历史分页、/web/api/status 快照、会话切换）排队到相互饿死。
109: // 存储不支持 SessionStorageMetadataReader 时回退到完整 Get，语义不变。
110: func (m *SessionManager) GetMetadata(ctx context.Context, sessionID string) (*Session, error) {
111: 	reader, ok := m.storage.(SessionStorageMetadataReader)
112: 	if !ok {
113: 		return m.Get(ctx, sessionID)
114: 	}
115: 
116: 	session, err := reader.LoadMetadata(ctx, sessionID)
117: 	if err != nil {
118: 		return nil, fmt.Errorf("failed to load session metadata: %w", err)
119: 	}
120: 
121: 	// 过期检查与 Get 保持同一条语义：过期即回收并报 ErrSessionExpired。
122: 	if session.IsExpired() {
123: 		_ = m.storage.Delete(ctx, sessionID)
124: 		return nil, ErrSessionExpired
125: 	}
126: 
127: 	return session, nil
128: }
