107: // Save 保存会话
108: func (s *InMemoryStorage) Save(ctx context.Context, session *Session) error {
109: 	if session == nil {
110: 		return ErrInvalidSession
111: 	}
112: 	if err := ctx.Err(); err != nil {
113: 		return err
114: 	}
115: 
116: 	s.mu.Lock()
117: 	defer s.mu.Unlock()
118: 
119: 	if session.ID == "" {
120: 		session.ID = generateSessionID()
121: 	}
122: 
123: 	if session.CreatedAt.IsZero() {
124: 		session.CreatedAt = time.Now()
125: 	}
126: 
127: 	if !session.PreserveUpdatedAt {
128: 		session.UpdatedAt = time.Now()
129: 	}
130: 
131: 	stored := session.Clone()
132: 	if stored == nil {
133: 		return ErrInvalidSession
134: 	}
135: 	stored.PreserveUpdatedAt = false
136: 	s.sessions[stored.ID] = stored
137: 
138: 	// 更新标签索引
139: 	s.updateTagIndex(stored)
140: 
141: 	return nil
142: }
