199: // ensureReadPool 惰性打开读池：仅在写池已 init 成功（schema 就绪）后调用。
200: // 打开/校验失败时降级（sticky）并计数，不影响调用方本次读（回落写池）。
201: func (s *SQLiteRuntimeStore) ensureReadPool(ctx context.Context) {
202: 	if s == nil || !s.fileBacked || s.disableReadPool || s.readPoolSize <= 0 || strings.TrimSpace(s.readDSN) == "" {
203: 		return
204: 	}
205: 	if ctx != nil && ctx.Err() != nil {
206: 		return
207: 	}
208: 	s.readPoolMu.Lock()
209: 	defer s.readPoolMu.Unlock()
210: 	if s.readDB != nil || s.readPoolDegraded {
211: 		return
212: 	}
213: 	db, err := sql.Open("sqlite3", s.readDSN)
214: 	if err != nil {
215: 		s.degradeReadPoolLocked(fmt.Errorf("open: %w", err))
216: 		return
217: 	}
218: 	db.SetMaxOpenConns(s.readPoolSize)
219: 	db.SetMaxIdleConns(runtimeReadPoolMaxIdleConns)
220: 	openCtx, cancel := context.WithTimeout(context.Background(), runtimeReadPoolOpenTimeout)
221: 	defer cancel()
222: 	if err := db.PingContext(openCtx); err != nil {
223: 		_ = db.Close()
224: 		s.degradeReadPoolLocked(fmt.Errorf("ping: %w", err))
225: 		return
226: 	}
227: 	if err := verifyRuntimeReadPoolPragmas(openCtx, db, s.readBusyTimeout.Milliseconds(), s.readQueryOnly); err != nil {
228: 		_ = db.Close()
229: 		s.degradeReadPoolLocked(err)
230: 		return
231: 	}
232: 	s.readDB = db
233: 	s.readPoolOpen = true
234: }
