236: // verifyRuntimeReadPoolPragmas 读回逐连接 PRAGMA，确认 DSN `_pragma` 真正生效。
237: func verifyRuntimeReadPoolPragmas(ctx context.Context, db *sql.DB, busyTimeoutMs int64, queryOnly bool) error {
238: 	if db == nil {
239: 		return fmt.Errorf("read pool is not open")
240: 	}
241: 	if queryOnly {
242: 		var mode int
243: 		if err := db.QueryRowContext(ctx, "PRAGMA query_only").Scan(&mode); err != nil {
244: 			return fmt.Errorf("verify query_only: %w", err)
245: 		}
246: 		if mode != 1 {
247: 			return fmt.Errorf("read pool query_only = %d, want 1", mode)
248: 		}
249: 	}
250: 	var timeout int64
251: 	if err := db.QueryRowContext(ctx, "PRAGMA busy_timeout").Scan(&timeout); err != nil {
252: 		return fmt.Errorf("verify busy_timeout: %w", err)
253: 	}
254: 	if timeout != busyTimeoutMs {
255: 		return fmt.Errorf("read pool busy_timeout = %d, want %d", timeout, busyTimeoutMs)
256: 	}
257: 	var cacheKiB int64
258: 	if err := db.QueryRowContext(ctx, "PRAGMA cache_size").Scan(&cacheKiB); err != nil {
259: 		return fmt.Errorf("verify cache_size: %w", err)
260: 	}

