25: // read it from the live node record.
26: 
27: // SessionBinding is the persistent preference record of one chat session.
28: type SessionBinding struct {
29: 	SchemaVersion     int          `json:"schema_version"`
30: 	SessionID         string       `json:"session_id"`
31: 	Preferred         *BindingAddr `json:"preferred,omitempty"`
32: 	LastNodeID        string       `json:"last_node_id,omitempty"`
33: 	LastWorkspacePath string       `json:"last_workspace_path,omitempty"`
34: 	UpdatedAt         time.Time    `json:"updated_at"`
35: }
36: 
37: // BindingAddr is the preferred host/port pair stored in a binding.
38: type BindingAddr struct {
39: 	Host string `json:"host,omitempty"`
40: 	Port int    `json:"port,omitempty"`
41: }
42: 
43: // BindingUpdate is what a serving node publishes for one session.
44: type BindingUpdate struct {
45: 	SessionID     string
46: 	Host          string
47: 	Port          int
48: 	NodeID        string
49: 	WorkspacePath string
50: }
51: 
52: // LoadBinding reads mesh/bindings/<session_id>.json.
53: //
54: // A missing, unreadable, malformed or unknown-schema file — or a port outside
55: // 1..65535 — all mean "no usable binding" (ok=false), so the caller falls back
56: // to a random port exactly like the pre-mesh port record did.
57: func LoadBinding(paths Paths, sessionID string) (SessionBinding, bool) {
58: 	path := paths.BindingPath(sessionID)
59: 	if path == "" {
60: 		return SessionBinding{}, false
61: 	}
62: 	data, err := os.ReadFile(path)
63: 	if err != nil {
64: 		return SessionBinding{}, false
65: 	}
66: 	var binding SessionBinding
67: 	if err := json.Unmarshal(data, &binding); err != nil {
68: 		return SessionBinding{}, false
69: 	}
70: 	if binding.SchemaVersion != SchemaVersion {
71: 		return SessionBinding{}, false
72: 	}
73: 	if binding.Preferred == nil || binding.Preferred.Port < 1 || binding.Preferred.Port > 65535 {
74: 		return SessionBinding{}, false
75: 	}
76: 	if strings.TrimSpace(binding.SessionID) == "" {
77: 		binding.SessionID = strings.TrimSpace(sessionID)
78: 	}
79: 	return binding, true
80: }
