82: // SaveBinding writes a binding atomically (0644 — it holds no secrets).
83: //
84: // Writing is fail-closed: with an unresolved mesh root the call is a silent
85: // no-op, never a CWD-relative fallback. An unusable session id is a caller bug
86: // and is reported as an error.
87: func SaveBinding(paths Paths, binding SessionBinding) error {
88: 	if !paths.Enabled() {
89: 		return nil
90: 	}
91: 	path := paths.BindingPath(binding.SessionID)
92: 	if path == "" {
93: 		return fmt.Errorf("mesh: invalid session id %q for a binding", binding.SessionID)
94: 	}
95: 	if binding.Preferred != nil && (binding.Preferred.Port < 1 || binding.Preferred.Port > 65535) {
96: 		return fmt.Errorf("mesh: invalid binding port %d (want 1..65535)", binding.Preferred.Port)
97: 	}
98: 	if binding.SchemaVersion == 0 {
99: 		binding.SchemaVersion = SchemaVersion
100: 	}
101: 	if binding.UpdatedAt.IsZero() {
102: 		binding.UpdatedAt = NowUTC()
103: 	}

