416: // writeRawEvent 入队一个预渲染帧（mesh 扇入）：payload 是 data 行的原始 JSON
417: // 字节，id 是 SSE 续传游标。非阻塞，payload 由发布方共享（只读，不再复制）。
418: func (s *chatWebSSEStream) writeRawEvent(event, id string, payload []byte) {
