425: // keepalive 入队一行 SSE 注释帧（`: keepalive`），维持连接存活。非阻塞。
426: func (s *chatWebSSEStream) keepalive() {
427: 	s.enqueue(chatWebSSEFrame{keepalive: true})
428: }
