430: // flush 入队一个 keepalive 帧并等待其被 writer goroutine 写出，用于流式
431: // 响应收尾时确认最终结果帧已落盘；超时或队列满/流已死返回 false。
432: func (s *chatWebSSEStream) flush(timeout time.Duration) bool {
433: 	if s == nil || s.Closed() {
434: 		return false
435: 	}
436: 	if timeout <= 0 {
437: 		timeout = 2 * time.Second
438: 	}
439: 	ack := make(chan struct{})
440: 	select {
441: 	case s.queue <- chatWebSSEFrame{keepalive: true, ack: ack}:
442: 	default:
443: 		return false
444: 	}
445: 	timer := time.NewTimer(timeout)
446: 	defer timer.Stop()
447: 	select {
448: 	case <-ack:
449: 		return true
450: 	case <-s.done:
451: 		return false
452: 	case <-timer.C:
453: 		return false
454: 	}
455: }
