457: // lastEventAge 返回距最近一次成功写入的时间（无锁原子读）。
458: func (s *chatWebSSEStream) lastEventAge() time.Duration {
459: 	if s == nil {
460: 		return 0
461: 	}
462: 	return time.Since(time.Unix(0, s.lastAt.Load()))
463: }
