465: // start 启动专用 writer goroutine。onDead 在流判死时调用（通常用于退订
466: // EventBus），最多触发一次。
467: func (s *chatWebSSEStream) start(onDead func()) {
468: 	if s == nil {
469: 		return
470: 	}
471: 	go s.runWriter(onDead)
472: }
