474: // Close 幂等关闭流（handler 退出时调用）；未写出的帧被丢弃。
475: func (s *chatWebSSEStream) Close() {
476: 	if s == nil {
477: 		return
478: 	}
479: 	s.closeOnce.Do(func() {
480: 		s.dead.Store(true)
481: 		close(s.done)
482: 	})
483: }
484: 
485: // fail 把流判死：关闭 Done、回调 onDead（均只一次）。
486: func (s *chatWebSSEStream) fail(onDead func()) {
487: 	if s == nil || !s.dead.CompareAndSwap(false, true) {
488: 		return
489: 	}
490: 	s.closeOnce.Do(func() { close(s.done) })
491: 	if onDead != nil {
492: 		onDead()
493: 	}
494: }
