496: // enqueue 非阻塞入队：队列满或流已死时丢帧并计数，绝不阻塞调用方。
497: func (s *chatWebSSEStream) enqueue(f chatWebSSEFrame) {
498: 	if s == nil || s.dead.Load() {
499: 		if s != nil {
500: 			s.dropped.Add(1)
501: 		}
502: 		return
503: 	}
504: 	select {
505: 	case s.queue <- f:
506: 	default:
507: 		s.dropped.Add(1)
508: 	}
509: }
