511: // runWriter 是唯一写 socket 的 goroutine：逐帧写 + Flush，均带写截止时间。
512: func (s *chatWebSSEStream) runWriter(onDead func()) {
513: 	defer close(s.writerDone)
514: 	timeout := s.writeTimeout
515: 	if timeout <= 0 {
516: 		timeout = chatWebSSEWriteTimeout
517: 	}
518: 	for {
519: 		select {
520: 		case f := <-s.queue:
521: 			if err := s.writeFrame(s.renderFrame(f), timeout); err != nil {
522: 				s.fail(onDead)
523: 				return
524: 			}
525: 			if f.ack != nil {
526: 				close(f.ack)
527: 			}
528: 		case <-s.done:
529: 			return
530: 		}
531: 	}
532: }
