534: // renderFrame 生成帧字节。writer goroutine 独占调用，sequence 按 FIFO 单调。
535: func (s *chatWebSSEStream) renderFrame(f chatWebSSEFrame) []byte {
536: 	var sb strings.Builder
537: 	if f.keepalive {
538: 		sb.WriteString(": keepalive\n\n")
539: 		return []byte(sb.String())
540: 	}
541: 	if f.id != "" {
542: 		sb.WriteString("id: ")
543: 		sb.WriteString(f.id)
544: 		sb.WriteString("\n")
545: 	}
546: 	sb.WriteString("event: ")
547: 	sb.WriteString(f.event)
548: 	sb.WriteString("\ndata: ")
549: 	switch {
550: 	case f.payload != nil:
551: 		// 预渲染载荷（mesh 扇入帧）：字节由发布方生成且只读，不再追加 _event
552: 		// 信封——seq / ts / source_node_id 已在载荷内（§6.3）。
553: 		sb.Write(f.payload)
554: 	case f.data != nil:
555: 		f.data["_event"] = map[string]interface{}{
556: 			"sequence":       s.seq.Add(1),
557: 			"schema_version": chatWebSchemaVersion,
558: 			"timestamp":      time.Now().UTC().Format(time.RFC3339),
559: 			"source_event":   f.sourceEvent,
560: 		}
561: 		payload, err := json.Marshal(f.data)
562: 		if err != nil {
563: 			s.dropped.Add(1)
564: 			return nil
565: 		}
566: 		sb.Write(payload)
567: 	}
568: 	sb.WriteString("\n\n")
569: 	return []byte(sb.String())
570: }
