384: 	snap := buildChatWebScreenSnapshotFull()
385: 	if !snap.Available || len(snap.Messages) == 0 {
386: 		// 无会话 / 无结构化消息：保持原响应形状（前端按 available 处理）。
387: 		return snap
388: 	}
389: 	unfilteredTotal := len(snap.Messages)
390: 	snap.Messages = filter.apply(snap.Messages)
391: 	matchedTotal := len(snap.Messages)
392: 	// 在过滤后的序列上做窗口裁剪（0 命中时 windowChatWebMessages 会早退，
393: 	// 需要下面补齐分页元信息，前端才能显示「匹配 0 / 共 M 条」）。
394: 	windowChatWebMessages(snap, window)
