396: 		snap.MessageWindow = &chatWebMessageWindowInfo{}
397: 	}
398: 	snap.MessageWindow.Total = matchedTotal
399: 	snap.MessageWindow.UnfilteredTotal = unfilteredTotal
400: 	// 过滤改变了消息集合：lines/text 必须按过滤后的消息重建（无论窗口是否激活）。
401: 	lines := chatWebLinesForMessages(snap.Messages)
402: 	snap.Lines = lines
403: 	snap.Text = strings.Join(lines, "\n")
