209: 	}
210: 
211: 	// Folder trust (R2): block project-scoped MCP configs when untrusted.
212: 	// User-global (~/.aicli, ~/.config/aicli) paths remain allowed.
213: 	if !sessionProjectScopeAllowed(session) {
214: 		projectRoot := folderTrustProjectRoot(session)
215: 		if foldertrust.IsProjectScopedPath(configPath, projectRoot) {
216: 			return "", false
217: 		}
218: 	}
