51: // A leading "~" in explicitPath is expanded to the current user's home
52: // directory; other explicit values are returned exactly as configured.
53: func ResolveConfigFilePath(filename, explicitPath, portableDefault string, searchPaths []string) string {
54: 	filename = strings.TrimSpace(filename)
55: 	if filename == "" {
56: 		return strings.TrimSpace(explicitPath)
57: 	}
