59: 	explicitPath = expandExplicitConfigPath(explicitPath)
60: 	if explicitPath != "" && !isConventionConfigPath(explicitPath, filename, portableDefault, searchPaths) {
61: 		return explicitPath
62: 	}
63: 
64: 	// Project-level override: ./.aicli/<filename> in CWD
65: 	if cwd, err := os.Getwd(); err == nil {
66: 		projectConfig := filepath.Join(cwd, ".aicli", filename)
67: 		if info, err := os.Stat(projectConfig); err == nil && !info.IsDir() {
68: 			return filepath.Clean(projectConfig)
69: 		}
70: 	}
71: 
72: 	// User-level default: $HOME/.aicli/<filename>
73: 	if home, err := os.UserHomeDir(); err == nil && home != "" {
74: 		userConfig := filepath.Join(home, ".aicli", filename)
75: 		if info, err := os.Stat(userConfig); err == nil && !info.IsDir() {
76: 			return userConfig
77: 		}
78: 	}
79: 
80: 	// CWD upward search
81: 	if cwd, err := os.Getwd(); err == nil {
82: 		if resolved := resolveDefaultConfigPathFromBase(cwd, filename, searchPaths); resolved != "" {
83: 			return resolved
84: 		}
85: 	}
