163: func TestResolveMCPConfigPathPrefersProjectThenUserAICLIDirs(t *testing.T) {
164: 	home := t.TempDir()
165: 	isolateHome(t, home)
166: 
167: 	userConfig := filepath.Join(home, ".aicli", DefaultMCPConfigFileName)
168: 	if err := os.MkdirAll(filepath.Dir(userConfig), 0o755); err != nil {
169: 		t.Fatalf("create user mcp dir: %v", err)
170: 	}
171: 	if err := os.WriteFile(userConfig, []byte("mcp_servers: {}\n"), 0o644); err != nil {
172: 		t.Fatalf("write user mcp config: %v", err)
173: 	}
174: 
175: 	projectDir := t.TempDir()
176: 	projectConfig := filepath.Join(projectDir, ".aicli", DefaultMCPConfigFileName)
177: 	if err := os.MkdirAll(filepath.Dir(projectConfig), 0o755); err != nil {
178: 		t.Fatalf("create project mcp dir: %v", err)
179: 	}
180: 	if err := os.WriteFile(projectConfig, []byte("mcp_servers: {}\n"), 0o644); err != nil {
181: 		t.Fatalf("write project mcp config: %v", err)
182: 	}
183: 	t.Chdir(projectDir)
184: 
185: 	// The template default value (configs/mcp.yaml) is a convention path and
186: 	// must fall through to the .aicli lookups instead of being returned as-is.
187: 	if got := ResolveMCPConfigPath(DefaultMCPConfigRelativePath); got != projectConfig {
188: 		t.Fatalf("project-level mcp config = %q, want %q", got, projectConfig)
189: 	}
190: 
191: 	// Outside the project directory the user-level file wins.
192: 	nestedDir := filepath.Join(projectDir, "nested")
193: 	if err := os.MkdirAll(nestedDir, 0o755); err != nil {
194: 		t.Fatalf("create nested dir: %v", err)
195: 	}
196: 	t.Chdir(nestedDir)
197: 	if got := ResolveMCPConfigPath(DefaultMCPConfigRelativePath); got != userConfig {
198: 		t.Fatalf("user-level mcp config = %q, want %q", got, userConfig)
199: 	}
200: 
201: 	// An explicit, non-convention override still wins.
202: 	override := filepath.Join(t.TempDir(), "selected-mcp.yaml")
203: 	if got := ResolveMCPConfigPath(override); got != override {
204: 		t.Fatalf("explicit mcp config = %q, want %q", got, override)
205: 	}
206: 
207: 	// Empty stays empty so callers keep "MCP not configured" semantics.
208: 	if got := ResolveMCPConfigPath(""); got != "" {
209: 		t.Fatalf("empty mcp config = %q, want empty", got)
210: 	}
211: }
