43: func TestResolveRuntimeMCPConfigResolutionFallsBackToUserLevel(t *testing.T) {
44: 	home := isolateMCPResolutionHome(t)
45: 	t.Chdir(t.TempDir())
46: 
47: 	// resolver 会从 cwd 逐级向上搜索（docs/aicli/install.md：每级先 .aicli/mcp.yaml，
48: 	// 再 configs/mcp.yaml）。开发机上 %TEMP% 位于用户主目录之下时，祖先链上真实的
49: 	// ~/.aicli/mcp.yaml 会先命中，此时不存在“任何候选都不存在”的前提 —— 这是环境
50: 	// 事实而非缺陷（干净环境如 CI 仍会执行下面的断言），跳过而不是误报失败。
51: 	if probe := aiclipaths.ResolveMCPConfigPath(aiclipaths.DefaultMCPConfigRelativePath); filepath.ToSlash(probe) != aiclipaths.DefaultMCPConfigRelativePath {
52: 		t.Skipf("环境提供祖先 mcp.yaml：解析到 %s（向上搜索按文档命中），跳过 user-fallback 断言", probe)
53: 	}
54: 
55: 	cfg := &config.Config{AICLI: &config.AICLIConfig{MCP: &config.AICLIMCPConfig{ConfigFile: "configs/mcp.yaml"}}}
56: 	resolution := resolveRuntimeMCPConfigResolution(cfg)
57: 	want := filepath.Join(home, ".aicli", "mcp.yaml")
58: 	if resolution.Path != want || resolution.Source != "user-fallback" {
