321: 		t.Fatalf("resolution = %+v, want path=%q source=project", resolution, projectConfig)
322: 	}
323: 	if want := ResolveMCPConfigPath(DefaultMCPConfigRelativePath); resolution.Path != want {
324: 		t.Fatalf("detailed path = %q, ResolveMCPConfigPath = %q", resolution.Path, want)
325: 	}
326: 
327: 	projectCandidateFound := false
328: 	for _, candidate := range resolution.Candidates {
329: 		if candidate.Path == projectConfig {
