161:     }
162:     res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
163:     return res.end(JSON.stringify(handler(url)));
164:   }
165:   if (url.pathname.startsWith("/web/api/")) {
166:     res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
167:     return res.end(JSON.stringify({ status: "ok" }));
